<template>
  <div class="page-content">
    <h1 class="w3-text-teal">Danh sách môn học</h1>
    <div class="table-responsive mt-3">
      <table class="table table-bordered table-hover">
        <thead><tr>
          <th style="width: 100px">Id</th>
          <th>Tên</th>
          <th style="width: 120px">Thao tác</th>
        </tr></thead>
        <tbody>
          <tr v-for="item in ds" :key="item.Id">
            <td>{{ item.Id }}</td>
            <td>{{ item.Ten }}</td>
            <td><b-button size="sm" variant="primary" @click="edit(item.Id)">Sửa</b-button></td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</template>

<script>
import { getModuleBase, getItems } from './crudStore'

export default {
  name: 'GenericList',
  data() { return { ds: [] } },
  activated() { this.loadData() },
  created() { this.loadData() },
  watch: { '$route.fullPath'() { this.loadData() } },
  methods: {
    loadData() { this.ds = getItems(getModuleBase(this.$route)) },
    edit(id) {
      const base = getModuleBase(this.$route)
      this.$router.push(`${base}/Edit/${encodeURIComponent(id)}`)
    }
  }
}
</script>
