// Demo data per module. Replace with real API when ready.
const seed = [
  { Id: 1, Ten: 'Môn Toán' },
  { Id: 2, Ten: 'Môn Lý' },
  { Id: 3, Ten: 'Môn Hóa' }
]

export function getModuleBase(route) {
  // Nested routes have their parent registered in matched[0].
  // This works for modules with any name (Admin, MonHoc, ...).
  const parent = route && route.matched && route.matched[0]
  if (parent && parent.path && parent.path !== '/') {
    return parent.path.replace(/\/$/, '')
  }
  // Fallback for standalone routes.
  const segments = (route && route.path ? route.path : '').split('/').filter(Boolean)
  return segments.length ? '/' + segments[0] : ''
}

function storageKey(moduleBase) {
  return 'vue2-demo-crud:' + moduleBase
}

export function getItems(moduleBase) {
  try {
    const raw = localStorage.getItem(storageKey(moduleBase))
    if (raw !== null) {
      const items = JSON.parse(raw)
      if (Array.isArray(items)) return items
    }
  } catch (e) {
    // For browsers where localStorage is disabled, keep demo available.
  }
  return seed.map(item => ({ ...item }))
}

export function saveItem(moduleBase, record) {
  const items = getItems(moduleBase)
  const index = items.findIndex(x => String(x.Id) === String(record.Id))
  if (index >= 0) items.splice(index, 1, { ...record })
  else items.push({ ...record })
  localStorage.setItem(storageKey(moduleBase), JSON.stringify(items))
}
